#include "scope.h"
#include <limits.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"OW_CHECK OCS line%d: %s\n",__LINE__,#x);return 1;}}while(0)
static int policy(void){struct ocs_plan p={3,{OW_ALWAYS,OW_ON_SUCCESS,OW_ON_ERROR},0,ER_IO};struct ocs_report r={0};unsigned effects=0;CHECK(ocs_run(&p,&effects,&r)==OW_OK&&effects==3&&r.original==ER_IO&&r.converted==ER_CONTRACT&&r.count==2&&r.trace[0]==3&&r.trace[1]==1);p.raised=ER_OK;CHECK(ocs_run(&p,&effects,&r)==OW_OK&&effects==6&&r.count==2&&r.trace[0]==2&&r.trace[1]==1);puts("OCS_POLICY actual-conditional-LIFO skips-consumed effects-retained");return 0;}
static int jump(void){struct ocs_plan p={4,{OW_ALWAYS,OW_ON_ERROR,OW_ON_SUCCESS,OW_ALWAYS},0,ER_THROWN};struct ocs_report r={0};unsigned effects=11;CHECK(ocs_run(&p,&effects,&r)==OW_OK&&effects==15&&r.original==ER_THROWN&&r.converted==ER_CONTRACT&&r.registered==4&&r.count==3);for(unsigned i=0;i<r.count;++i)CHECK(r.seen_error[i]==ER_CONTRACT);for(unsigned cut=1;cut<=4;++cut){p.fail_before=cut;CHECK(ocs_run(&p,&effects,&r)==OW_OK&&r.original==ER_IO&&r.registered==cut-1);for(unsigned i=0;i<r.count;++i)CHECK(r.seen_error[i]==ER_CONTRACT);}unsigned before=effects;p.policy[3]=(enum ow_when)9;struct ocs_report old=r;CHECK(ocs_run(&p,&effects,&r)==OW_INVALID&&effects==before&&!memcmp(&old,&r,sizeof(r)));puts("OCS_JUMP actual-er-run conversion-before-scope every-registration-cut");return 0;}
struct ow_probe {struct ow_scope scope;unsigned callbacks,bad;};
static void probe(void *p){struct ow_probe *q=p;++q->callbacks;size_t n=q->scope.count;if(ow_defer(&q->scope,probe,q,OW_ALWAYS)!=OW_INVALID||ow_finish(&q->scope,1)!=OW_INVALID||q->scope.count!=n)q->bad=1;}
static int capacity(void){struct ow_probe p={0};for(unsigned i=0;i<8;++i)CHECK(ow_defer(&p.scope,probe,&p,OW_ALWAYS)==OW_OK);CHECK(ow_defer(&p.scope,probe,&p,OW_ALWAYS)==OW_FULL&&p.scope.count==8);CHECK(ow_finish(&p.scope,2)==OW_INVALID&&p.scope.count==8);CHECK(ow_finish(&p.scope,1)==OW_OK&&p.callbacks==8&&!p.bad&&!p.scope.count);CHECK(ow_finish(&p.scope,0)==OW_OK&&p.callbacks==8);puts("OCS_CAPACITY eight-nine reentry-rejected popped-before-callback");return 0;}
struct ow_pub {struct ow_allocator pool;struct v4_allocator raw;struct ow_owner *published,*staged;int32_t *expected;unsigned inspect,bad,observed;};
static int32_t *pub_take(void *p,size_t n){struct ow_pub *q=p;return q->raw.take(q->raw.context,n);}
static void pub_release(void *p,int32_t *b){struct ow_pub *q=p;if(q->inspect){++q->observed;if(q->published->count!=3||q->published->block[0]!=q->expected||q->staged->count!=0||q->published->block[0][0]!=97)q->bad=1;}q->raw.release(q->raw.context,b);}
static int publish(void){struct ow_pub p={0};p.raw=ow_allocator(&p.pool);struct v4_allocator a={&p,pub_take,pub_release};struct ow_owner old={0},fresh={0};size_t n[3]={1,2,3};CHECK(ow_construct(&old,a,n)==OW_OK&&ow_construct(&fresh,a,n)==OW_OK);fresh.block[0][0]=97;p.published=&old;p.staged=&fresh;p.expected=fresh.block[0];p.inspect=1;CHECK(ow_publish(&old,&fresh)==OW_OK&&!p.bad&&p.observed==3&&p.pool.live==3&&!fresh.count);p.inspect=0;CHECK(ow_destroy(&old)==OW_OK&&!p.pool.live&&p.pool.releases==6);puts("OCS_PUBLISH actual-swap before-old-cleanup matching-allocator");return 0;}
struct ow_resources {struct ocs_recovery *owner;struct ocs_ticket ticket;unsigned retain,error,owned[8],calls[8],trace[32],count,bad,probe;struct ow_allocator pool;struct v4_allocator raw;int32_t *block[8];};
static int resource_open(struct ow_resources *r,unsigned id){if(!r->raw.take)r->raw=ow_allocator(&r->pool);r->block[id]=r->raw.take(r->raw.context,1);if(!r->block[id])return 0;r->block[id][0]=(int32_t)id;r->owned[id]=1;return 1;}
static enum ocs_close close_resource(void *p,unsigned id){struct ow_resources *r=p;if(id>=8||!r->owned[id]){r->bad=1;return OCS_RELEASED;}if(r->count<32)r->trace[r->count++]=id;else r->bad=1;++r->calls[id];if(!r->owner->finishing)r->bad=1;if(r->probe){struct ocs_recovered out={91,92,93};if(ocs_push(r->ticket,close_resource,r,7)!=OW_BUSY||ocs_recover(r->ticket,&out)!=OW_BUSY||out.pending!=91)r->bad=1;}if((r->retain&(1u<<id))&&r->calls[id]==1)return OCS_RETAINED;r->raw.release(r->raw.context,r->block[id]);r->block[id]=NULL;r->owned[id]=0;return r->error&(1u<<id)?OCS_RELEASED_ERROR:OCS_RELEASED;}
static int recovery(void){struct ocs_recovery owner={0};struct ow_resources r={0};r.owner=&owner;r.retain=4;r.error=4;r.probe=1;CHECK(ocs_begin(&owner,&r.ticket)==OW_OK);for(unsigned i=0;i<3;++i){CHECK(resource_open(&r,i));CHECK(ocs_push(r.ticket,close_resource,&r,i)==OW_OK);}struct ocs_recovered out={0};CHECK(ocs_recover(r.ticket,&out)==OW_BUSY&&out.pending==3&&out.close_errors==0&&out.recovery_required&&owner.active&&owner.count==3&&r.count==1&&r.trace[0]==2);CHECK(ocs_push(r.ticket,close_resource,&r,3)==OW_BUSY);CHECK(ocs_recover(r.ticket,&out)==OW_OK&&out.pending==0&&out.close_errors==1&&!out.recovery_required&&!owner.active&&!r.bad&&!r.pool.live);CHECK(r.count==4&&r.trace[1]==2&&r.trace[2]==1&&r.trace[3]==0);for(unsigned i=0;i<3;++i)CHECK(!r.owned[i]);out.pending=91;CHECK(ocs_recover(r.ticket,&out)==OW_STALE&&out.pending==91);puts("OCS_RECOVERY retained-stops-dependency-unwind released-error-never-retried sealed-set");return 0;}
static int identity(void){struct ocs_recovery owner={0};struct ow_resources r={0};r.owner=&owner;CHECK(ocs_begin(&owner,&r.ticket)==OW_OK);struct ocs_ticket old=r.ticket;struct ocs_recovered out={0};CHECK(ocs_recover(r.ticket,&out)==OW_OK);CHECK(ocs_begin(&owner,&r.ticket)==OW_OK);out.pending=91;CHECK(ocs_recover(old,&out)==OW_STALE&&out.pending==91);for(unsigned i=0;i<8;++i){CHECK(resource_open(&r,i));CHECK(ocs_push(r.ticket,close_resource,&r,i)==OW_OK);}CHECK(ocs_push(r.ticket,close_resource,&r,9)==OW_FULL);CHECK(ocs_recover(r.ticket,&out)==OW_OK&&!r.bad);owner.generation=UINT32_MAX-1;CHECK(ocs_begin(&owner,&r.ticket)==OW_OK&&r.ticket.generation==UINT32_MAX);CHECK(resource_open(&r,0));CHECK(ocs_push(r.ticket,close_resource,&r,0)==OW_OK&&ocs_recover(r.ticket,&out)==OW_OK);old=r.ticket;CHECK(ocs_begin(&owner,&r.ticket)==OW_RETIRED&&r.ticket.generation==old.generation&&!owner.active);puts("OCS_IDENTITY stale-generation capacity final-epoch-cleanup-no-wrap");return 0;}
static int oracle(void){unsigned kind,n,packed,cut,raised;while(scanf("%u %u %u %u %u",&kind,&n,&packed,&cut,&raised)==5){if(kind==0){struct ocs_plan p={0};p.count=n;p.fail_before=cut;p.raised=(er_code)raised;for(unsigned i=0;i<n&&i<8;++i){p.policy[i]=(enum ow_when)(packed%3);packed/=3;}unsigned effects=7;struct ocs_report r={0};enum ow_status s=ocs_run(&p,&effects,&r);printf("%d %u %d %d %u %u",s,effects,r.original,r.converted,r.registered,r.count);for(unsigned i=0;i<r.count;++i)printf(" %u %u",r.trace[i],r.seen_error[i]);putchar('\n');}else{struct ocs_recovery owner={0};struct ow_resources r={0};r.owner=&owner;r.retain=packed;r.error=cut;if(ocs_begin(&owner,&r.ticket)!=OW_OK)return 1;for(unsigned i=0;i<n;++i){if(!resource_open(&r,i))return 1;if(ocs_push(r.ticket,close_resource,&r,i)!=OW_OK)return 1;}struct ocs_recovered out={0};unsigned attempts=0;enum ow_status s;do{s=ocs_recover(r.ticket,&out);++attempts;}while(s==OW_BUSY&&attempts<=9);printf("%d %u %u %u %u %u",s,attempts,out.pending,out.close_errors,r.bad||(r.pool.live!=0),r.count);for(unsigned i=0;i<r.count;++i)printf(" %u",r.trace[i]);putchar('\n');}}return ferror(stdin)?2:0;}
static int metrics(void){struct ocs_plan p={4,{OW_ALWAYS,OW_ON_ERROR,OW_ON_SUCCESS,OW_ALWAYS},0,ER_IO};unsigned effects=0,sum=0;double samples[7];for(unsigned s=0;s<7;++s){clock_t start=clock();for(unsigned i=0;i<10000;++i){struct ocs_report out;CHECK(ocs_run(&p,&effects,&out)==OW_OK);sum+=out.count+out.registered;}samples[s]=(double)(clock()-start)/CLOCKS_PER_SEC;}printf("{\"iterations\":10000,\"checksum\":%u,\"external_effects\":%u,\"recovery_size\":%zu,\"seconds\":[",sum,effects,sizeof(struct ocs_recovery));for(unsigned i=0;i<7;++i)printf("%s%.9f",i?",":"",samples[i]);puts("]}");return 0;}
int main(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"scope_policy"))return policy();if(!strcmp(argv[1],"scope_jump"))return jump();if(!strcmp(argv[1],"scope_capacity"))return capacity();if(!strcmp(argv[1],"scope_publish"))return publish();if(!strcmp(argv[1],"scope_recovery"))return recovery();if(!strcmp(argv[1],"scope_identity"))return identity();if(!strcmp(argv[1],"oracle"))return oracle();if(!strcmp(argv[1],"metrics"))return metrics();return 2;}
